  void sse_encode_box_autoadd_u_64(BigInt self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_u_64(self, serializer);
  }

  @protected
  void sse_encode_list_String(List<String> self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_i_32(self.length, serializer);
    for (final item in self) {
      sse_encode_String(item, serializer);
    }
  }

  @protected
  void sse_encode_list_list_prim_u_8_strict(
    List<Uint8List> self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_i_32(self.length, serializer);
    for (final item in self) {
      sse_encode_list_prim_u_8_strict(item, serializer);
    }
  }

  @protected
  void sse_encode_list_prim_u_8_loose(
    List<int> self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_i_32(self.length, serializer);
    serializer.buffer.putUint8List(
      self is Uint8List ? self : Uint8List.fromList(self),
    );
  }

  @protected
  void sse_encode_list_prim_u_8_strict(
    Uint8List self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_i_32(self.length, serializer);
    serializer.buffer.putUint8List(self);
  }

  @protected
  void sse_encode_list_record_list_prim_u_8_strict_list_prim_u_8_strict(
    List<(Uint8List, Uint8List)> self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_i_32(self.length, serializer);
    for (final item in self) {
      sse_encode_record_list_prim_u_8_strict_list_prim_u_8_strict(
        item,
        serializer,
      );
    }
  }

  @protected
  void sse_encode_opt_box_autoadd_u_64(BigInt? self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs

    sse_encode_bool(self != null, serializer);
    if (self != null) {
      sse_encode_box_autoadd_u_64(self, serializer);
    }
  }

  @protected
  void sse_encode_opt_list_prim_u_8_strict(
    Uint8List? self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs

    sse_encode_bool(self != null, serializer);
    if (self != null) {
      sse_encode_list_prim_u_8_strict(self, serializer);
    }
  }

  @protected
  void sse_encode_record_list_prim_u_8_strict_list_prim_u_8_strict(
    (Uint8List, Uint8List) self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_list_prim_u_8_strict(self.$1, serializer);
    sse_encode_list_prim_u_8_strict(self.$2, serializer);
  }

  @protected
  void sse_encode_storage_stats(StorageStats self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_u_64(self.physicalBytes, serializer);
    sse_encode_u_64(self.logicalBytes, serializer);
    sse_encode_u_64(self.tableCount, serializer);
    sse_encode_u_64(self.openSnapshots, serializer);
    sse_encode_u_64(self.commitSequence, serializer);
  }

  @protected
  void sse_encode_u_64(BigInt self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    serializer.buffer.putBigUint64(self);
  }

  @protected
  void sse_encode_u_8(int self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    serializer.buffer.putUint8(self);
  }

  @protected
  void sse_encode_unit(void self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
  }

  @protected
  void sse_encode_usize(BigInt self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    serializer.buffer.putBigUint64(self);
  }

  @protected
  void sse_encode_i_32(int self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    serializer.buffer.putInt32(self);
  }
}

@sealed
class NativeWorkerImpl extends RustOpaque implements NativeWorker {
  // Not to be used by end users
  NativeWorkerImpl.frbInternalDcoDecode(List<dynamic> wire)
    : super.frbInternalDcoDecode(wire, _kStaticData);

  // Not to be used by end users
  NativeWorkerImpl.frbInternalSseDecode(BigInt ptr, int externalSizeOnNative)
    : super.frbInternalSseDecode(ptr, externalSizeOnNative, _kStaticData);

  static final _kStaticData = RustArcStaticData(
    rustArcIncrementStrongCount:
        RustLib.instance.api.rust_arc_increment_strong_count_NativeWorker,
    rustArcDecrementStrongCount:
        RustLib.instance.api.rust_arc_decrement_strong_count_NativeWorker,
    rustArcDecrementStrongCountPtr:
        RustLib.instance.api.rust_arc_decrement_strong_count_NativeWorkerPtr,
  );

  Future<BigInt> applyBatch({required List<int> encodedOps}) => RustLib
      .instance
      .api
      .crateApiNativeWorkerApplyBatch(that: this, encodedOps: encodedOps);

  /// Explicitly releases the redb file handle before the Dart object is
  /// dropped. This is required for deterministic reopen on Windows.
  Future<void> close() =>
      RustLib.instance.api.crateApiNativeWorkerClose(that: this);

  Future<BigInt> commitSequence() =>
      RustLib.instance.api.crateApiNativeWorkerCommitSequence(that: this);

  /// Compacts the database file in place (redb's supported compact path).
  /// Returns true when compaction reclaimed space, false when the file was
  /// already fully compacted. Fails with a typed error if any MVCC snapshot
  /// is still open or the database is read-only.
  Future<bool> compact() =>
      RustLib.instance.api.crateApiNativeWorkerCompact(that: this);

  /// Returns the compatibility handshake before callers use the worker.
  Future<String> compatibilityHandshake() => RustLib.instance.api
      .crateApiNativeWorkerCompatibilityHandshake(that: this);

  /// Creates a point-in-time MVCC snapshot handle (a held redb read
  /// transaction). Reads through the returned id observe the committed state
  /// at creation time, not later writes.
  Future<BigInt> createSnapshot() =>
      RustLib.instance.api.crateApiNativeWorkerCreateSnapshot(that: this);

  Future<void> dropSnapshot({required BigInt snapshot}) => RustLib.instance.api
      .crateApiNativeWorkerDropSnapshot(that: this, snapshot: snapshot);

  Future<Uint8List?> get_({required String table, required List<int> key}) =>
      RustLib.instance.api.crateApiNativeWorkerGet(
        that: this,
        table: table,
        key: key,
      );

  /// M3: batched point-read — fetches N keys in ONE read transaction,
  /// returning `(key, row)` pairs for keys that exist. Absent keys are
  /// omitted; a missing table is an empty result, never an error. Kills the
  /// relationship N+1 (one boundary crossing instead of one per id).
  Future<List<(Uint8List, Uint8List)>> getMany({
    required String table,
    required List<Uint8List> keys,
  }) => RustLib.instance.api.crateApiNativeWorkerGetMany(
    that: this,
    table: table,
    keys: keys,
  );

  /// Phase 2 step 2: full-scan with a pushed predicate. Scans every row in
  /// [table], evaluates [predicate] against each row's encoded bytes IN RUST
  /// (decoding only the referenced fields), and returns only the matching
  /// `(recordId, row)` pairs in one hop. Non-matching rows are never decoded
  /// in Dart. [predicate_bytes] is the Dart-serialized `Predicate` payload.
  Future<List<(Uint8List, Uint8List)>> queryFiltered({
    required String table,
    required List<int> predicateBytes,
  }) => RustLib.instance.api.crateApiNativeWorkerQueryFiltered(
    that: this,
    table: table,
    predicateBytes: predicateBytes,
  );

  /// M3: aggregate pushdown — counts matching rows WITHOUT transferring
  /// them. Scans [table], evaluates [predicate_bytes] against each row's
  /// bytes IN RUST, and returns only the count. A `count()` query no longer
  /// pays the decode + transfer cost of every matching row.
  Future<BigInt> queryFilteredCount({
    required String table,
    required List<int> predicateBytes,
  }) => RustLib.instance.api.crateApiNativeWorkerQueryFilteredCount(
    that: this,
    table: table,
    predicateBytes: predicateBytes,
  );

  /// M3: aggregate pushdown — emits only the bytes of [field] for each
  /// matching row, so a `distinct(field)` query transfers one value per row
  /// instead of the whole row. Returns a list of raw encoded `RowValue`
  /// bytes (the slice starting at the value's tag byte, self-delimiting
  /// under the codec); the Dart side decodes and dedups them. Rows where
  /// [field] is absent are omitted (matches Dart `distinct()`).
  Future<List<Uint8List>> queryFilteredDistinct({
    required String table,
    required List<int> predicateBytes,
    required String field,
  }) => RustLib.instance.api.crateApiNativeWorkerQueryFilteredDistinct(
    that: this,
    table: table,
    predicateBytes: predicateBytes,
    field: field,
  );

  /// M4: full-scan + predicate with an early LIMIT/OFFSET — skips the first
  /// [offset] matches and returns at most [limit] of the rest, stopping the
  /// scan as soon as the window fills (matching rows beyond it are never
  /// transferred).
  Future<List<(Uint8List, Uint8List)>> queryFilteredLimited({
    required String table,
    required List<int> predicateBytes,
    BigInt? limit,
    required BigInt offset,
  }) => RustLib.instance.api.crateApiNativeWorkerQueryFilteredLimited(
    that: this,
    table: table,
    predicateBytes: predicateBytes,
    limit: limit,
    offset: offset,
  );

  /// Phase 2 native query fast path: range-scans the durable index table
  /// [index_table] for keys in `[start..=end]`, joins each entry's value
  /// (the user-table row key) back to its row in [table], and returns the
  /// `(recordId, row)` pairs in one hop. [start]/[end] are the already
  /// codec-encoded `[table, field, value, ...]` key bounds. Eliminates the
  /// Dart-side N+1 (one boundary crossing instead of one per candidate id).
  Future<List<(Uint8List, Uint8List)>> queryIndexed({
    required String table,
    required String indexTable,
    required List<int> start,
    required List<int> end,
  }) => RustLib.instance.api.crateApiNativeWorkerQueryIndexed(
    that: this,
    table: table,
    indexTable: indexTable,
    start: start,
    end: end,
  );

  /// M4: index-served query with an early LIMIT/OFFSET. Streams the durable
  /// index range `[start..=end]`, joins to rows, applies [predicate_bytes]
  /// (so early-stop is correct with additional filters), and stops once the
  /// window fills.
  Future<List<(Uint8List, Uint8List)>> queryIndexedLimited({
    required String table,
    required String indexTable,
    required List<int> start,
    required List<int> end,
    required List<int> predicateBytes,
    BigInt? limit,
    required BigInt offset,
  }) => RustLib.instance.api.crateApiNativeWorkerQueryIndexedLimited(
    that: this,
    table: table,
    indexTable: indexTable,
    start: start,
    end: end,
    predicateBytes: predicateBytes,
    limit: limit,
    offset: offset,
  );

  /// M4: index-ordered early-stop sort. Streams the durable-index range
  /// `[start..=end]` in index-key order (the same order Dart's stable sort of
  /// the field produces), joins to rows, applies [predicate_bytes], and
  /// stops once `offset + limit` matches are collected. [eq_bounded]
  /// indicates `start..=end` is an equality bound on [sort_field] (so
  /// index-key order is correct for either direction); when false, the
  /// stream covers all values of [sort_field] (ascending only; missing-field
  /// rows are appended if the window is not filled).
  Future<List<(Uint8List, Uint8List)>> queryIndexedOrdered({
    required String table,
    required String indexTable,
    required List<int> start,
    required List<int> end,
    required List<int> predicateBytes,
    required String sortField,
    required bool eqBounded,
    BigInt? limit,
    required BigInt offset,
  }) => RustLib.instance.api.crateApiNativeWorkerQueryIndexedOrdered(
    that: this,
    table: table,
    indexTable: indexTable,
    start: start,
    end: end,
    predicateBytes: predicateBytes,
    sortField: sortField,
    eqBounded: eqBounded,
    limit: limit,
    offset: offset,
  );

  /// M4: full-scan + top-K sort. Evaluates [predicate_bytes] and returns the
  /// `[offset, offset+limit)` window ordered by [sort_spec_bytes] (a port of
  /// Dart `compareRows`), keeping only the window in memory — the full
  /// candidate set is never materialized or transferred.
  Future<List<(Uint8List, Uint8List)>> querySorted({
    required String table,
    required List<int> predicateBytes,
    required List<int> sortSpecBytes,
    BigInt? limit,
    required BigInt offset,
  }) => RustLib.instance.api.crateApiNativeWorkerQuerySorted(
    that: this,
    table: table,
    predicateBytes: predicateBytes,
    sortSpecBytes: sortSpecBytes,
    limit: limit,
    offset: offset,
  );

  Future<List<(Uint8List, Uint8List)>> rangeScan({
    required String table,
    Uint8List? start,
    Uint8List? end,
  }) => RustLib.instance.api.crateApiNativeWorkerRangeScan(
    that: this,
    table: table,
    start: start,
    end: end,
  );

  Future<Uint8List?> snapshotGet({
    required BigInt snapshot,
    required String table,
    required List<int> key,
  }) => RustLib.instance.api.crateApiNativeWorkerSnapshotGet(
    that: this,
    snapshot: snapshot,
    table: table,
    key: key,
  );

  /// Snapshot-bound variant of [Self::get_many]: every read observes one
  /// consistent committed state.
  Future<List<(Uint8List, Uint8List)>> snapshotGetMany({
    required BigInt snapshot,
    required String table,
    required List<Uint8List> keys,
  }) => RustLib.instance.api.crateApiNativeWorkerSnapshotGetMany(
    that: this,
    snapshot: snapshot,
    table: table,
    keys: keys,
  );

  /// Snapshot-bound variant of [Self::query_filtered]: the scan + predicate
  /// evaluation observe one consistent committed state.
  Future<List<(Uint8List, Uint8List)>> snapshotQueryFiltered({
    required BigInt snapshot,
    required String table,
    required List<int> predicateBytes,
  }) => RustLib.instance.api.crateApiNativeWorkerSnapshotQueryFiltered(
    that: this,
    snapshot: snapshot,
    table: table,
    predicateBytes: predicateBytes,
  );

  /// Snapshot-bound variant of [Self::query_filtered_count].
  Future<BigInt> snapshotQueryFilteredCount({
    required BigInt snapshot,
    required String table,
    required List<int> predicateBytes,
  }) => RustLib.instance.api.crateApiNativeWorkerSnapshotQueryFilteredCount(
    that: this,
    snapshot: snapshot,
    table: table,
    predicateBytes: predicateBytes,
  );

  /// Snapshot-bound variant of [Self::query_filtered_distinct].
  Future<List<Uint8List>> snapshotQueryFilteredDistinct({
    required BigInt snapshot,
    required String table,
    required List<int> predicateBytes,
    required String field,
  }) => RustLib.instance.api.crateApiNativeWorkerSnapshotQueryFilteredDistinct(
    that: this,
    snapshot: snapshot,
    table: table,
    predicateBytes: predicateBytes,
    field: field,
  );

  /// Snapshot-bound variant of [Self::query_filtered_limited].
  Future<List<(Uint8List, Uint8List)>> snapshotQueryFilteredLimited({
    required BigInt snapshot,
    required String table,
    required List<int> predicateBytes,
    BigInt? limit,
    required BigInt offset,
  }) => RustLib.instance.api.crateApiNativeWorkerSnapshotQueryFilteredLimited(
    that: this,
    snapshot: snapshot,
    table: table,
    predicateBytes: predicateBytes,
    limit: limit,
    offset: offset,
  );

  /// Snapshot-bound variant of [Self::query_indexed]: reads through an
  /// existing MVCC snapshot so the index→row join observes one consistent
  /// committed state.
  Future<List<(Uint8List, Uint8List)>> snapshotQueryIndexed({
    required BigInt snapshot,
    required String table,
    required String indexTable,
    required List<int> start,
    required List<int> end,
  }) => RustLib.instance.api.crateApiNativeWorkerSnapshotQueryIndexed(
    that: this,
    snapshot: snapshot,
    table: table,
    indexTable: indexTable,
    start: start,
    end: end,
  );

  /// Snapshot-bound variant of [Self::query_indexed_limited].
  Future<List<(Uint8List, Uint8List)>> snapshotQueryIndexedLimited({
    required BigInt snapshot,
    required String table,
    required String indexTable,
    required List<int> start,
    required List<int> end,
    required List<int> predicateBytes,
    BigInt? limit,
    required BigInt offset,
  }) => RustLib.instance.api.crateApiNativeWorkerSnapshotQueryIndexedLimited(
    that: this,
    snapshot: snapshot,
    table: table,
    indexTable: indexTable,
    start: start,
    end: end,
    predicateBytes: predicateBytes,
    limit: limit,
    offset: offset,
  );

  /// M5: intersects multiple durable-index candidate ranges in one
  /// snapshot-bound operation and rechecks the complete predicate in Rust.
  Future<List<(Uint8List, Uint8List)>> snapshotQueryIndexedMulti({
    required BigInt snapshot,
    required String table,
    required String indexTable,
    required List<(Uint8List, Uint8List)> ranges,
    required List<int> predicateBytes,
  }) => RustLib.instance.api.crateApiNativeWorkerSnapshotQueryIndexedMulti(
    that: this,
    snapshot: snapshot,
    table: table,
    indexTable: indexTable,
    ranges: ranges,
    predicateBytes: predicateBytes,
  );

  /// Snapshot-bound variant of [Self::query_indexed_ordered].
  Future<List<(Uint8List, Uint8List)>> snapshotQueryIndexedOrdered({
    required BigInt snapshot,
    required String table,
    required String indexTable,
    required List<int> start,
    required List<int> end,
    required List<int> predicateBytes,
    required String sortField,
    required bool eqBounded,
    BigInt? limit,
    required BigInt offset,
  }) => RustLib.instance.api.crateApiNativeWorkerSnapshotQueryIndexedOrdered(
    that: this,
    snapshot: snapshot,
    table: table,
    indexTable: indexTable,
    start: start,
    end: end,
    predicateBytes: predicateBytes,
    sortField: sortField,
    eqBounded: eqBounded,
    limit: limit,
    offset: offset,
  );

  /// Snapshot-bound variant of [Self::query_sorted].
  Future<List<(Uint8List, Uint8List)>> snapshotQuerySorted({
    required BigInt snapshot,
    required String table,
    required List<int> predicateBytes,
    required List<int> sortSpecBytes,
    BigInt? limit,
    required BigInt offset,
  }) => RustLib.instance.api.crateApiNativeWorkerSnapshotQuerySorted(
    that: this,
    snapshot: snapshot,
    table: table,
    predicateBytes: predicateBytes,
    sortSpecBytes: sortSpecBytes,
    limit: limit,
    offset: offset,
  );

  Future<List<(Uint8List, Uint8List)>> snapshotRangeScan({
    required BigInt snapshot,
    required String table,
    Uint8List? start,
    Uint8List? end,
  }) => RustLib.instance.api.crateApiNativeWorkerSnapshotRangeScan(
    that: this,
    snapshot: snapshot,
    table: table,
    start: start,
    end: end,
  );

  /// Reports physical/logical size and health counters (Workstream 5).
  Future<StorageStats> storageStats() =>
      RustLib.instance.api.crateApiNativeWorkerStorageStats(that: this);

  Future<List<String>> tables() =>
      RustLib.instance.api.crateApiNativeWorkerTables(that: this);
